<script setup lang="ts">
/**
 * Reset Password Page
 *
 * Password reset form, opened from the link in the reset email.
 * Generated by Blacksmith. You own this file — customize as needed.
 */
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import type { FormSubmitEvent } from '@nuxt/ui'
import type { z } from 'zod'
import UButton from '@nuxt/ui/components/Button.vue'
import UForm from '@nuxt/ui/components/Form.vue'
import UFormField from '@nuxt/ui/components/FormField.vue'
import UInput from '@nuxt/ui/components/Input.vue'
import { Path } from '@/router/paths'
import TextLink from '@/shared/components/TextLink.vue'
import { useAuth } from '../composables/use-auth'
import { resetPasswordSchema } from '../schemas'
import AuthPanel from '../components/AuthPanel.vue'

const props = defineProps<{
  /** From the URL, `/reset-password/:token` */
  token: string
}>()

const router = useRouter()
const { confirmPasswordReset, error } = useAuth()

const state = reactive({ password: '' })
const submitting = ref(false)

async function onSubmit(event: FormSubmitEvent<z.output<typeof resetPasswordSchema>>) {
  submitting.value = true
  try {
    const result = await confirmPasswordReset(props.token, event.data.password)
    if (result.success) {
      await router.replace(Path.Login)
    }
  } finally {
    submitting.value = false
  }
}
</script>

<template>
  <AuthPanel title="Choose a new password" description="Enter your new password below." :error="error?.message">
    <UForm
      :schema="resetPasswordSchema"
      :state="state"
      class="flex flex-col gap-4"
      @submit="onSubmit"
    >
      <UFormField label="New password" name="password" required>
        <UInput
          v-model="state.password"
          type="password"
          autocomplete="new-password"
          placeholder="Choose a new password"
          size="lg"
          class="w-full"
        />
      </UFormField>

      <UButton
        type="submit"
        size="lg"
        block
        :loading="submitting"
        class="mt-2"
      >
        Reset password
      </UButton>
    </UForm>

    <template #footer>
      <TextLink :to="Path.Login">
        Back to log in
      </TextLink>
    </template>
  </AuthPanel>
</template>
